const D = { density:.55, energy:.6, speed:1, scale:1, warp:.55, hue:212, x:.5, y:.5, style:'pigment', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
let sr = (P.seed * 2654435761) >>> 0;
function rnd() { sr ^= sr << 13; sr >>>= 0; sr ^= sr >> 17; sr ^= sr << 5; sr >>>= 0; return sr / 4294967295; }

// recursively deform a polygon: subdivide each edge, displacing the midpoint (organic watercolor edge)
function deform(pts, depth, rough) {
  for (let d = 0; d < depth; d++) {
    const out = [];
    const n = pts.length;
    for (let i = 0; i < n; i++) {
      const a = pts[i], b = pts[(i + 1) % n];
      out.push(a);
      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.sqrt(dx*dx + dy*dy);
      const disp = (rnd() - 0.5) * len * rough;
      // displace along the edge normal
      out.push({ x: mx + (-dy/ (len||1)) * disp, y: my + (dx/(len||1)) * disp });
    }
    pts = out;
    rough *= 0.62;   // finer detail each level
  }
  return pts;
}
function baseBlob(cx, cy, rad, nsides, irreg) {
  const pts = [];
  for (let i = 0; i < nsides; i++) {
    const a = (i / nsides) * TAU;
    const rr = rad * (1 - irreg * 0.5 + rnd() * irreg);
    pts.push({ x: cx + Math.cos(a) * rr, y: cy + Math.sin(a) * rr * 0.92 });
  }
  return pts;
}

// palette per style
function pigments() {
  const hb = P.hue;
  if (style === 'sumi')       return [[wh(hb),4,14],[wh(hb),6,22],[wh(hb),3,9]];
  if (style === 'monochrome') return [[wh(hb),60,55],[wh(hb+12),55,45],[wh(hb-12),65,62]];
  if (style === 'sunset')     return [[wh(hb),82,92],[wh(hb+28),85,88],[wh(hb-30),70,80],[wh(hb+52),80,86]];
  if (style === 'botanical')  return [[wh(140),70,70],[wh(96),62,66],[wh(38),72,84],[wh(300),55,64]];
  // pigment (default) — jewel bleed
  return [[wh(hb),78,84],[wh(hb+120),70,78],[wh(hb+220),74,82],[wh(hb+300),68,80],[wh(hb+60),72,86]];
}

// (re)build the layered blob set — cached; rebuild on seed / section / count change
const NB = 4 + Math.round(P.density * 8);
const LAYERS = 10 + Math.round(P.energy * 8);
const sec = K.section | 0;
if (!S.blobs || S.nb !== NB || S.secUsed !== sec || S.seedUsed !== P.seed || S.styUsed !== style) {
  S.nb = NB; S.secUsed = sec; S.seedUsed = P.seed; S.styUsed = style;
  sr = ((P.seed + sec * 101) * 2654435761) >>> 0;
  const pal = pigments();
  S.blobs = [];
  for (let b = 0; b < NB; b++) {
    const cx = width * (0.1 + rnd() * 0.8);
    const cy = height * (0.12 + rnd() * 0.76);
    const rad = u * (0.10 + rnd() * 0.16) * (0.6 + P.scale * 0.8);
    const col = pal[(Math.floor(rnd() * pal.length)) % pal.length];
    // pre-deform LAYERS variants (each a differently-jittered organic polygon)
    const layers = [];
